527	func TestConcurrentSessionLifecycleHTTP(t *testing.T) {
528		h, _ := newTestHandler(t)
529		registerDevice(t, h, "dev")
530	
531		// Concurrent identical creates: exactly one creator.
532		const n = 40
533		var wg sync.WaitGroup
534		var mu sync.Mutex
535		creators := 0
536		errs := make(chan error, n)
537		for i := 0; i < n; i++ {
538			wg.Add(1)
539			go func() {
540				defer wg.Done()
541				w, body := postJSON(t, h, "/v1/devices/dev/sessions", map[string]any{"sessionId": "hot"})
542				if w.Code != http.StatusOK {
543					errs <- fmt.Errorf("status %d: %s", w.Code, w.Body.String())
544					return
545				}
546				if body["created"] == true {
547					mu.Lock()
548					creators++
549					mu.Unlock()
550				}
551			}()
552		}
553		wg.Wait()
554		close(errs)
555		for err := range errs {
556			t.Fatal(err)
557		}
558		if creators != 1 {
559			t.Fatalf("creators = %d, want 1", creators)
560		}
561	
562		// Concurrent delete vs. create: in the end exactly one of {live, absent}
563		// holds consistently, and the next state is coherent (repeat delete 404s
564		// iff the delete won; create reports created=true iff it ran after removal).
565		var wg2 sync.WaitGroup
566		statuses := make(chan int, 2)
567		wg2.Add(2)
568		go func() {
569			defer wg2.Done()
570			w, _ := doRequest(t, h, http.MethodDelete, "/v1/devices/dev/sessions/hot")
571			statuses <- w.Code
572		}()
573		go func() {
574			defer wg2.Done()
575			w, _ := postJSON(t, h, "/v1/devices/dev/sessions", map[string]any{"sessionId": "hot"})
576			statuses <- w.Code
577		}()
578		wg2.Wait()
579		close(statuses)
580		for code := range statuses {
581			if code != http.StatusOK {
582				t.Fatalf("racing delete/create status = %d", code)
583			}
584		}
585	
586		// The race settles into exactly one coherent state (live or absent). A
587		// final owner delete then forces "absent": 200 if it was live, 404 if the
588		// racing delete already won. Afterwards both the read and a repeat delete
589		// must observe the same absent state — no half-deleted or duplicated row.
590		w, _ := doRequest(t, h, http.MethodDelete, "/v1/devices/dev/sessions/hot")
591		if w.Code != http.StatusOK && w.Code != http.StatusNotFound {
592			t.Fatalf("settling delete = %d", w.Code)
593		}
594		w, _ = doRequest(t, h, http.MethodGet, "/v1/sessions/hot/documents/d/changes")
595		if w.Code != http.StatusNotFound {
596			t.Fatalf("session should be absent after settle, GET = %d", w.Code)
597		}
598		w, _ = doRequest(t, h, http.MethodDelete, "/v1/devices/dev/sessions/hot")
599		if w.Code != http.StatusNotFound {
600			t.Fatalf("repeat delete after settle = %d, want 404", w.Code)
601		}
602	}
