262	// All 404 cases answer the same terse JSON error and reveal nothing about
263	// other devices' subscriptions; checks run shape -> device -> ownership.
264	func TestSubscriptionManagementNotFoundCases(t *testing.T) {
265		srv, _ := newWSTestServer(t)
266		setupSession(t, srv, "dev-1", "sess-1", "doc", 0)
267		registerDeviceViaHTTP(t, srv, "dev-2")
