275	
276		cases := []struct {
277			name   string
278			method string
279			path   string
280		}{
281			{"unregistered device lists", http.MethodGet, "/v1/devices/ghost/subscriptions"},
282			{"unregistered device cancels", http.MethodDelete, "/v1/devices/ghost/subscriptions/" + id},
283			{"unknown subscription id", http.MethodDelete, "/v1/devices/dev-1/subscriptions/sub-nope"},
284			{"subscription owned by another device", http.MethodDelete, "/v1/devices/dev-2/subscriptions/" + id},
285		}
286		for _, tc := range cases {
287			t.Run(tc.name, func(t *testing.T) {
