291				}
292				var errBody map[string]string
293				if err := json.Unmarshal([]byte(body), &errBody); err != nil || errBody["error"] == "" {
294					t.Fatalf("body = %q, want a JSON error", body)
295				}
296				if strings.Contains(body, id) || strings.Contains(body, "doc") {
297					t.Fatalf("error body leaks subscription content: %q", body)
298				}
299			})
300		}
301	
302		// The foreign cancel left the real connection live and unpushed.
303		conn.setReadDeadline(300 * time.Millisecond)
304		if _, _, _, ok := conn.readFrameMaybe(); ok {
305			t.Fatal("a rejected foreign cancel disturbed the connection")
306		}
307		conn.clearReadDeadline()
308	
309		// The real owner cancels successfully; an immediate repeat is a 404 that
310		// changes nothing.
311		if status, _, _ := rawRequest(t, srv, http.MethodDelete, "/v1/devices/dev-1/subscriptions/"+id); status != http.StatusOK {
312			t.Fatalf("first cancel = %d, want 200", status)
313		}
314		if code := conn.readCloseCode(); code != 4410 {
315			t.Fatalf("close code = %d, want 4410", code)
316		}
317		status, _, body := rawRequest(t, srv, http.MethodDelete, "/v1/devices/dev-1/subscriptions/"+id)
318		if status != http.StatusNotFound {
319			t.Fatalf("repeat cancel = %d (%s), want 404", status, body)
320		}
321	}
