323	// Every malformed shape — empty identifier, trailing slash, missing or extra
324	// segment, wrong method — is a JSON 400 before any device lookup, never a
325	// redirect or HTML.
326	func TestSubscriptionManagementBadShape(t *testing.T) {
327		h, _ := newTestHandler(t)
328		registerDevice(t, h, "dev-1")
329	
330		cases := []struct {
331			name   string
332			method string
333			path   string
334		}{
335			{"empty device segment on list", http.MethodGet, "/v1/devices//subscriptions"},
336			{"trailing slash on list", http.MethodGet, "/v1/devices/dev-1/subscriptions/"},
337			{"trailing slash on item", http.MethodDelete, "/v1/devices/dev-1/subscriptions/sub-1/"},
338			{"delete missing the id segment", http.MethodDelete, "/v1/devices/dev-1/subscriptions"},
339			{"extra segment on item", http.MethodDelete, "/v1/devices/dev-1/subscriptions/sub-1/extra"},
340			{"post on the collection", http.MethodPost, "/v1/devices/dev-1/subscriptions"},
341			{"put on the collection", http.MethodPut, "/v1/devices/dev-1/subscriptions"},
342			{"get on the item path", http.MethodGet, "/v1/devices/dev-1/subscriptions/sub-1"},
343			{"put on the item path", http.MethodPut, "/v1/devices/dev-1/subscriptions/sub-1"},
344			{"get with an extra segment", http.MethodGet, "/v1/devices/dev-1/subscriptions/sub-1/extra"},
345		}
346		for _, tc := range cases {
347			t.Run(tc.name, func(t *testing.T) {
348				r := httptest.NewRequest(tc.method, tc.path, nil)
349				rec := httptest.NewRecorder()
350				h.ServeHTTP(rec, r)
351	
352				assertJSONErrorStatus(t, rec, http.StatusBadRequest)
353				if loc := rec.Header().Get("Location"); loc != "" {
354					t.Fatalf("malformed request produced a redirect to %q", loc)
355				}
356			})
357		}
358	}
