310		w, items = getAttachmentList(t, h, "/v1/devices/dev-2/attachments")
311		if w.Code != http.StatusOK || len(items) != 0 {
312			t.Fatalf("granted list after recreate = %d %v", w.Code, items)
313		}
314	}
