9	)
10	
11	func TestRegisterDeviceIdempotent(t *testing.T) {
12		s, _ := Open("")
13		defer func() { _ = s.Close() }()
14	
15		created, err := s.RegisterDevice("dev-1")
16		if err != nil || !created {
17			t.Fatalf("first register = created:%v err:%v", created, err)
18		}
19		created, err = s.RegisterDevice("dev-1")
20		if err != nil || created {
21			t.Fatalf("repeat register = created:%v err:%v", created, err)
22		}
23	
24		// A different id registers independently.
25		created, err = s.RegisterDevice("dev-2")
26		if err != nil || !created {
27			t.Fatalf("second device = created:%v err:%v", created, err)
28		}
29	}
30	
31	func TestCreateSessionOutcomes(t *testing.T) {
32		s, _ := Open("")
33		defer func() { _ = s.Close() }()
34	
35		// Unknown device -> ErrDeviceNotFound, nothing written.
36		if _, err := s.CreateSession("ghost", "sess"); !errors.Is(err, ErrDeviceNotFound) {
37			t.Fatalf("unknown device err = %v, want ErrDeviceNotFound", err)
38		}
39		if exists, err := s.SessionExists("sess"); err != nil || exists {
40			t.Fatalf("session should not exist after rejected create: exists=%v err=%v", exists, err)
41		}
42	
43		if _, err := s.RegisterDevice("dev-1"); err != nil {
44			t.Fatal(err)
45		}
46		if _, err := s.RegisterDevice("dev-2"); err != nil {
47			t.Fatal(err)
