611	
612		w, body := postJSON(t, h, "/v1/documents/doc1/snapshots", `{"cursor":1,"state":{"v":1}}`)
613		if w.Code != http.StatusOK || body["created"] != true {
614			t.Fatalf("first = %d %v", w.Code, body)
